import time

class SweepGuard:
    def __init__(self, max_entries_per_min=5):
        self.max_entries_per_min = max_entries_per_min
        self.entry_timestamps = []

    def enforce_rate_limit(self):
        current_time = time.time()
        self.entry_timestamps = [t for t in self.entry_timestamps if current_time - t < 60]
        return len(self.entry_timestamps) < self.max_entries_per_min

    def prioritize_signals(self, batch_signals):
        """Sorts signals by score and filters according to available slot capacity"""
        if not batch_signals:
            return []
        sorted_signals = sorted(batch_signals, key=lambda x: x.get('score', 0), reverse=True)
        available_slots = self.max_entries_per_min - len(self.entry_timestamps)
        return sorted_signals[:max(0, available_slots)]

